//! 🧪️ The existing native PagedMap is the original indexed record counterpart for the shared literal key corpus.
use semio_framework_value::paged::{PagedMap,PagedUtf8};
use semio_framework_value_testing_allocator as _;
use semio_framework_value::retained_clone::{RetainedCloneSource,RetainedCloneGrant};
#[test]
fn original_indexed_record_keeps_literal_key_order_and_actual_entry_addresses(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();let entries=fixture["entries"].as_array().unwrap();let original=PagedMap::<u64,1024>::try_from_entries(entries.iter().map(|row|(PagedUtf8::from(row[0].as_str().unwrap()),row[1].as_u64().unwrap()))).unwrap();let g=RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:1024*1024,maximum_capacity_bytes:1024*1024,maximum_release_bytes:1024*1024,maximum_depth:64};let(mut source,_)=RetainedCloneSource::admit_owned(original,(),g).unwrap_or_else(|_|panic!("genuine original indexed record"));assert_eq!(source.borrow().get().len(),entries.len());for(index,row)in entries.iter().enumerate(){let borrowed=source.borrow();let(key,value)=borrowed.get().entry_at(index).unwrap();assert!(key.eq_str(row[0].as_str().unwrap()));assert_eq!(*value,row[1].as_u64().unwrap());assert!(std::ptr::eq(value,borrowed.get().entry_at(index).unwrap().1));}assert!(source.borrow().get().entry_at(entries.len()).is_none());while !source.terminal_is_empty(){source.close_step(g).unwrap();}}
